Patient Portal.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

System_Ext(api_gateway_region_router, "API Gateway / Region Router", "Cloud Endpoints and Envoy routing cross-region traffic")

Container_Boundary(patient_portal, "Patient Portal") {
    Component(spa_router_view_manager, "SPA Router & View Manager", "React, Flutter", "Manages application views, user routing, and UI state for telehealth services.")
    Component(offline_storage_manager, "Offline Storage Manager", "IndexedDB, Web Crypto API (AES-GCM 256)", "Handles secure offline data persistence and encryption for resilient access.")
    Component(api_communication_client, "API Communication Client", "HTTPS, WSS, GCP Cloud CDN", "Transmits API requests, video telemetry, and real-time messaging to the region router.")
}

Rel(spa_router_view_manager, offline_storage_manager, "Persists and retrieves encrypted health data locally")
Rel(spa_router_view_manager, api_communication_client, "Initiates HTTP and WebSocket requests")
Rel(api_communication_client, api_gateway_region_router, "Routes API requests and telemetry via Cloud CDN", "HTTPS, WSS")
@enduml

API Gateway / Region Router.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the API Gateway / Region Router container

Container_Boundary(api_gateway_region_router, "API Gateway / Region Router") {
    Component(Edge Router & TLS Terminator, "Edge Router & TLS Terminator", "Envoy Proxy, Anycast", "Handles edge routing, TLS termination, HTTP/3 (QUIC) and WSS connectivity for unstable rural connections.")
    Component(Cloud Endpoints Gateway, "Cloud Endpoints Gateway", "Cloud Endpoints", "Manages API routing and request validation across EU and US regions.")
    Component(Geo-fencing & Context Injector, "Geo-fencing & Context Injector", "Envoy Filter / Go", "Enforces strict data residency and compliance by injecting context without modifying core microservices.")
}

Rel(Edge Router & TLS Terminator, Cloud Endpoints Gateway, "Forwards terminated HTTPS/WSS/QUIC traffic", "")
Rel(Cloud Endpoints Gateway, Geo-fencing & Context Injector, "Injects compliance and routing context", "")
@enduml

Audit & Compliance Reporting Service.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

title Component diagram for the Audit & Compliance Reporting Service container

Container_Boundary(audit_compliance_reporting_service, "Audit & Compliance Reporting Service") {
    Component(Log_Ingestion_Engine, "Log Ingestion Engine", "Go", "Ingests compliance and audit logs via gRPC over internal VPC.")
    Component(Jurisdictional_Storage_Router, "Jurisdictional Storage Router", "Go", "Routes logs and data to appropriate regional storage ensuring data residency.")
    Component(Report_Generation___Query_API, "Report Generation & Query API", "Node.js/GraphQL", "Provides GraphQL API for compliance reporting and dashboard queries.")
    Component(Compliance___Export_Orchestrator, "Compliance & Export Orchestrator", "Node.js", "Orchestrates compliance tasks and exports via Cloud Pub/Sub.")
}

Rel(Log_Ingestion_Engine, Jurisdictional_Storage_Router, "Passes log data via in-process calls", "")
Rel(Report_Generation___Query_API, Compliance___Export_Orchestrator, "Queries orchestration data and triggers reports", "")

@enduml

WebRTC SFU Media Server.diagram:
@startuml
!include https://raw.githubusercontent.com/plantuml-stdlib/C4-PlantUML/master/C4_Component.puml
LAYOUT_WITH_LEGEND()

Container_Boundary(webrtc_sfu_media_server, "WebRTC SFU Media Server") {
    Component(LiveKit_SFU_Node, "LiveKit SFU Node", "LiveKit, Go, WebRTC", "Handles real-time video and audio stream routing for consultations.")
    Component(Janus_Gateway, "Janus Gateway", "C, Janus, WebRTC", "Provides auxiliary media routing and fallback streaming capabilities.")
    Component(Bandwidth_Adapter, "Bandwidth Adapter", "Python, WebRTC", "Manages dynamic bitrate scaling and adaptive streaming for low-bandwidth rural environments.")
}

Rel(LiveKit_SFU_Node, Bandwidth_Adapter, "Sends stream metrics to")
Rel(Janus_Gateway, Bandwidth_Adapter, "Sends fallback stream metrics to")
@enduml
